        class R: text = "fake reply"
        return R()

class FakeClient:
    models = FakeModels()

def ask(prompt, client=None):
    if client is None:
        client = build_real_client()   # only when nothing was injected
    return client.models.generate_content(model="m", contents=prompt).text

